SELECT analytics_order_facts.channel, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 12 AND analytics_order_facts.region = 'East' AND analytics_order_facts.customer_segment = 'public' GROUP BY analytics_order_facts.channel ORDER BY contribution_margin DESC, analytics_order_facts.channel ASC LIMIT 12
